import sys

def is_anagram_brute(s, t):
    return sorted(s) == sorted(t)

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_anagram_brute(data[0], data[1]) else 'false')

import sys

def is_anagram_opt(s, t):
    if len(s) != len(t):
        return False
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - ord('a')] += 1
    for ch in t:
        idx = ord(ch) - ord('a')
        cnt[idx] -= 1
        if cnt[idx] < 0:
            return False
    return True

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_anagram_opt(data[0], data[1]) else 'false')

import sys
from collections import Counter

def is_anagram_best(s, t):
    if len(s) != len(t):
        return False
    diff = Counter()
    for a, b in zip(s, t):
        diff[a] += 1
        diff[b] -= 1
    return all(v == 0 for v in diff.values())

if __name__ == '__main__':
    data = sys.stdin.read().splitlines()
    if len(data) < 2:
        sys.exit(0)
    print('true' if is_anagram_best(data[0], data[1]) else 'false')
